CREATE TABLE "public"."partner schools" (
  "id"     bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"   text   NOT NULL,
  "domain" text   NOT NULL,
  CONSTRAINT "partner schools_domain_key" UNIQUE (DOMAIN),
  CONSTRAINT "partner schools_name_key" UNIQUE (name),
  CONSTRAINT "partner schools_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."partner schools"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Enable read access for all users" ON "public"."partner schools"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."partner schools" TO "anon", "authenticated", "postgres", "service_role";
